mapper.select:
SELECT COUNT(*)
  FROM emp01_person
 WHERE emp01_person_id  = #{personId}
   AND emp01_company_id = #{companyId}

mapper.update:
UPDATE emp01_person
   SET emp01_lock_yn = #{lockYn}
 WHERE emp01_person_id  = #{personId}
   AND emp01_company_id = #{companyId}

mapper.select:
SELECT a.sys25_seq
  FROM sys25_password a
 WHERE sys25_seq = (
                       SELECT MAX(sys.sys25_seq)
                         FROM sys25_password sys
                        WHERE sys.sys25_company_id = #{companyId}
                          AND sys.sys25_person_id = #{personId}
                   )
   AND sys25_person_id = #{personId}
   AND sys25_company_id = #{companyId}

mapper.update:
UPDATE sys25_password
   SET sys25_work_date = f_sysdate()
     , sys25_pwd = TO_ENCRYPTS(#{pwd,jdbcType=VARCHAR})
 WHERE sys25_person_id = #{personId}
   AND sys25_company_id = #{companyId}
   AND sys25_seq = #{seq}
